	levantamento as (
select
	e.codigo_inep || '-' || e.nome as unidade,
	t2.descricao as turno,
	ee.sigla as curso,
	count(distinct ts.id_turma_serie) as total_turmas,
	count(distinct mes.id_matricula_discente_serie) as total_alunos,
	count(distinct a.id_discente) as total_alunos_abaixo_media
from
	escola.escola e
join basico.turma_serie ts on
	ts.id_escola = e.id_escola
join ensino.turno t2 on
	ts.id_turno = t2.id_turno
join basico.serie s on
	s.id_serie = ts.id_serie
join basico.etapa_ensino ee on
	ee.id_etapa_ensino = s.id_etapa_ensino
join basico.matricula_estudante_serie mes on
	coalesce(mes.id_turma_serie_multisseriado,
	mes.id_turma_serie) = ts.id_turma_serie
left join alunos a on
	a.id_discente = mes.id_estudante
		and a.id_turma_serie = coalesce(mes.id_turma_serie_multisseriado,
		mes.id_turma_serie)
	where
		ts.ano = 2023
		and ts.ativo
