				and (case
					when ts.tipo_diario = 11 then mes.id_turma_serie_multisseriado is not null
					else true
				end)
			group by
				e.codigo_inep,
				ee.sigla,
				ee.sigla,
				t2.descricao,
				e.nome
			order by
				ee.sigla )
select
	l.unidade,
	l.curso,
	l.turno,
	l.total_turmas,
	l.total_alunos,
	l.total_alunos_abaixo_media,
	round((cast(l.total_alunos_abaixo_media as numeric)* 100 / l.total_alunos),
	2) as percent_alunos_abaixo_media
from
	levantamento l; 
	

